css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .64); position: relative; }
.loader .craft { position: absolute; left: 16%; top: 20%; width: 68%; height: 52%; animation: hover-float calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader .cabin { position: absolute; left: 16%; top: 0; width: 68%; height: 52%; border-radius: 42% 42% 12% 12% / 70% 70% 20% 20%; background: linear-gradient(var(--accent-2), var(--accent)); }
.loader .skirt { position: absolute; left: 0; bottom: 0; width: 100%; height: 44%; border-radius: 46%; background: color-mix(in srgb, var(--accent) 70%, transparent); box-shadow: inset 0 -3px 0 color-mix(in srgb, #000 22%, transparent); animation: hover-skirt calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader .ground { position: absolute; left: 4%; right: 4%; bottom: 8%; height: 4%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 30%, transparent); }
.loader i { position: absolute; bottom: 12%; width: 8%; height: 8%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: hover-dust calc(var(--loader-speed) * 1.2) ease-out infinite; }
.loader i:nth-of-type(1) { left: 10%; --dx: -70%; }
.loader i:nth-of-type(2) { left: 24%; --dx: -40%; animation-delay: calc(var(--loader-speed) * .3); }
.loader i:nth-of-type(3) { right: 24%; --dx: 40%; animation-delay: calc(var(--loader-speed) * .6); }
.loader i:nth-of-type(4) { right: 10%; --dx: 70%; animation-delay: calc(var(--loader-speed) * .9); }
@keyframes hover-float { 0%, 100% { transform: translateY(0) rotate(-1.5deg); } 50% { transform: translateY(-8%) rotate(1.5deg); } }
@keyframes hover-skirt { 0%, 100% { transform: scaleY(1) scaleX(1); } 50% { transform: scaleY(.82) scaleX(1.06); } }
@keyframes hover-dust { 0% { opacity: 0; transform: translate(0, 0) scale(.4); } 25% { opacity: .8; } 100% { opacity: 0; transform: translate(var(--dx, 0%), 40%) scale(1.4); } }
